c.arg(schema)::text)) IS NOT NULL AND to_regprocedure(format('%I.guard_version_disposal_verification()', sqlc.arg(schema)::text)) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_cleanup_jobs')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_cleanup_targets')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_cleanup_acknowledgements')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_destinations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_retention_guards')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_content_guards')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_job_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempt_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_result_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_job_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempt_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_result_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_inventory_guards')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempt_inventories')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempt_fact_inputs')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempt_memory_inputs')) IS NOT NULL AND to_regprocedure(format('%I.guard_live_version_reference()', sqlc.arg(schema)::text)) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'fact_version_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_version_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'fact_version_guards')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_version_guards')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'fact_version_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_version_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'context_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'context_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'snapshot_disposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'fact_snapshot_payloads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'pending_evidence_uploads')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'command_receipts')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'audit_exports')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'consumer_offsets')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'active_projections')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'decision_receipts')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'retention_events')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'conversations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_jobs')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_attempts')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'predicate_migrations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_versions')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_timeline_history')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'memory_attestations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'context_memory_items')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'decision_memory_items')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_memory_proposals')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_refresh_triggers')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_memory_targets')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_memory_dependencies')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'subject_lookup')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'scope_versions')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'subject_versions')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_subjects')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'confirmation_artifacts')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'attestation_delegations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'evidence_derivations')) IS NOT NULL AND to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_redactions')) IS NOT NULL AND EXISTS(SELECT 1
FROM pg_catalog.pg_attribute
WHERE attrelid=to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'projection_generations')) AND attname='verification_version' AND NOT attisdropped) AND EXISTS(SELECT 1
FROM pg_catalog.pg_attribute
WHERE attrelid=to_regclass(format('%I.%I', sqlc.arg(schema)::text, 'extraction_quota')) AND attname='reserved_cost_units' AND NOT attisdropped);
